const items = $input.all();
return items.map(() => {
  // NOTE: $json here is the passcode-hash lookup row, not the original
  // webhook payload — reference $('Webhook') explicitly for the request body.
  const body = ($('Webhook').first().json && $('Webhook').first().json.body) || {};

  // --- view ---
  const view = body.view === 'log' ? 'log' : 'overview';

  // --- overview: range -> [rangeStartIso, rangeEndIso] ---
  const rangeDaysMap = { '7d': 7, '30d': 30, '90d': 90 };
  const range = ['7d', '30d', '90d', 'all'].includes(body.range) ? body.range : '30d';
  const nowMs = Date.now();
  const rangeEndIso = new Date(nowMs).toISOString();
  const rangeStartIso = range === 'all'
    ? '1970-01-01T00:00:00.000Z'
    : new Date(nowMs - rangeDaysMap[range] * 24 * 60 * 60 * 1000).toISOString();

  // --- log: search / filter / page / pageSize ---
  const search = typeof body.search === 'string' ? body.search : '';
  const validFilters = ['all', 'unknown', 'voice', 'text', 'cache_hit', 'fresh'];
  const filterVal = validFilters.includes(body.filter) ? body.filter : 'all';

  let page = parseInt(body.page, 10);
  if (!Number.isFinite(page) || page < 1) page = 1;

  let pageSize = parseInt(body.pageSize, 10);
  if (!Number.isFinite(pageSize) || pageSize < 1) pageSize = 50;
  if (pageSize > 200) pageSize = 200; // guard against abuse

  const offset = (page - 1) * pageSize;

  return {
    json: {
      view,
      range,
      rangeStartIso,
      rangeEndIso,
      search,
      filterVal,
      page,
      pageSize,
      offset,
    },
  };
});

// The Postgres node returns one row with a single "result" column
// holding the whole JSON payload we built with json_build_object().
const first = $input.first();
const result = (first && first.json && first.json.result) || {};
return [{ json: result }];

